import{_ as a,o as r,c as o,a4 as e}from"./chunks/framework.DAD9IEko.js";const d=JSON.parse('{"title":"运动学基础与约束测验","description":"","frontmatter":{"date":"2026-06-13T00:00:00.000Z","section":"电机控制","chapter":"motion-control","chapterTitle":"运动控制","chapterOrder":30,"category":"运动控制","source":"motor","visibility":"public","title":"运动学基础与约束测验","tags":["motor-control"],"status":"learning","summary":"**问题:** 为什么jerk约束比加速度约束更难直接从电机参数推导？","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/motion-control/MC-TP-01-assessment.md","filePath":"content/motor/motion-control/MC-TP-01-assessment.md","lastUpdated":1783181958000}'),n={name:"content/motor/motion-control/MC-TP-01-assessment.md"};function s(m,t,p,i,l,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="运动学基础与约束测验" tabindex="-1">运动学基础与约束测验 <a class="header-anchor" href="#运动学基础与约束测验" aria-label="Permalink to &quot;运动学基础与约束测验&quot;">​</a></h1><h3 id="第1题-中等-jerk约束推导难点" tabindex="-1">第1题 [中等] - jerk约束推导难点 <a class="header-anchor" href="#第1题-中等-jerk约束推导难点" aria-label="Permalink to &quot;第1题 [中等] - jerk约束推导难点&quot;">​</a></h3><p><strong>问题:</strong> 为什么jerk约束比加速度约束更难直接从电机参数推导？</p><p><strong>参考答案:</strong> 加速度约束可以直接从电机力矩常数Kt和最大电流Imax推导：a_max = Kt·Imax / J_total，这是一个明确的电气-机械映射关系。而jerk（加加速度）约束没有直接的电气对应量，它取决于：（1）电流环的带宽和响应速度——电流变化率受逆变器电压裕度和电流环带宽限制；（2）机械系统的柔性——传动链的弹性变形会限制力矩变化率；（3）结构共振激励——过大的jerk会激发低频结构模态。因此jerk约束需要通过实验测量或系统辨识获得，而非从电机铭牌参数直接计算。</p><h3 id="第2题-较难-最大角加速度计算" tabindex="-1">第2题 [较难] - 最大角加速度计算 <a class="header-anchor" href="#第2题-较难-最大角加速度计算" aria-label="Permalink to &quot;第2题 [较难] - 最大角加速度计算&quot;">​</a></h3><p><strong>问题:</strong> 给定电机Kt=0.5Nm/A, Imax=10A, J_total=0.001kg·m²，计算最大角加速度。</p><p><strong>参考答案:</strong> 最大电磁力矩 T_max = Kt × Imax = 0.5 × 10 = 5 Nm。最大角加速度 α_max = T_max / J_total = 5 / 0.001 = 5000 rad/s²。注意：这是理论最大值，实际使用中需考虑：（1）电流裕量（通常只用80%左右）；（2）摩擦力矩会消耗部分力矩；（3）负载惯量变化时J_total会增大，导致实际加速度降低。换算为转速变化率约为 5000 × 60/(2π) ≈ 47746 rpm/s。</p><h3 id="第3题-较难-编码器分辨率与位置环kp下限" tabindex="-1">第3题 [较难] - 编码器分辨率与位置环Kp下限 <a class="header-anchor" href="#第3题-较难-编码器分辨率与位置环kp下限" aria-label="Permalink to &quot;第3题 [较难] - 编码器分辨率与位置环Kp下限&quot;">​</a></h3><p><strong>问题:</strong> 解释为什么编码器分辨率直接影响位置环的最低有效Kp。</p><p><strong>参考答案:</strong> 位置环的误差信号 e = θ_ref - θ_fb，其中θ_fb受编码器分辨率Δθ限制。当Kp过小时，Kp·Δθ产生的速度指令可能小于速度环的死区或最小分辨率，导致位置环无法响应单脉冲误差，产生稳态量化误差。有效Kp的下限满足：Kp_min × Δθ ≥ v_min（速度环最小可分辨速度指令）。例如，编码器分辨率为0.01°，速度环最小分辨率为1rpm，则Kp_min ≥ 1/(0.01×π/180×60) ≈ 955 (rpm/rad)。因此编码器分辨率越低，Kp下限越高，限制了位置环的精细调节能力。</p><h3 id="第4题-中等-相平面约束区域物理含义" tabindex="-1">第4题 [中等] - 相平面约束区域物理含义 <a class="header-anchor" href="#第4题-中等-相平面约束区域物理含义" aria-label="Permalink to &quot;第4题 [中等] - 相平面约束区域物理含义&quot;">​</a></h3><p><strong>问题:</strong> 在速度-加速度相平面上，约束边界围成的区域物理含义是什么？</p><p><strong>参考答案:</strong> 在v-a相平面上，约束边界（v_max水平线、±a_max水平线、以及由jerk约束决定的过渡曲线）围成的封闭区域表示系统在当前约束下所有可达的运动状态(v, a)集合。区域内部的任意点(v, a)都是物理可实现的——即存在一条合法轨迹使系统达到该状态而不违反任何约束。区域边界上的点是极限工作点，区域外部的点则不可达。这个区域也称为&quot;可行域&quot;或&quot;可达集&quot;，其面积越大表示系统的动态能力越强。在时间最优控制中，最优轨迹一定沿着可行域的边界运动。</p>',13)])])}const h=a(n,[["render",s]]);export{d as __pageData,h as default};
